  const relevant = (overwrites || []).filter(function (o) { return o && roleIds.indexOf(o.roleId) >= 0; });
  relevant.forEach(function (o) { if (o.view === "deny") view = false; });
  relevant.forEach(function (o) { if (o.view === "allow") view = true; });
